/** Tailwind `colors` overrides: every palette name → its Dash scale. */
function auroraColors() {
    return {
        gray: neutral,
        slate: neutral,
        zinc: neutral,
        neutral,
        stone: neutral,
        ...palette,
    };
}

// The accent scale is violet's.
const accent = palette.violet;

module.exports = { neutral, accent, palette, auroraColors };
